    foreach my $label (@labels) {
        $dns_query .= pack("C", length($label)) . $label;
    }
    $dns_query .= pack("C", 0);                  # null terminator

    # Query type A (1), class IN (1)
    $dns_query .= pack("n2", 1, 1);

    $socket->send($dns_query);

    my $response;
    $socket->recv($response, 512);

    if ($response) {
        print "Received response from audit resolver\n";
        # Parse DNS response header
        my ($id, $flags, $qdcount, $ancount, $nscount, $arcount) = unpack("n6", substr($response, 0, 12));
        print "DNS Response: ID=0x" . sprintf("%04x", $id) . ", Flags=0x" . sprintf("%04x", $flags) . "\n";
        print "Questions: $qdcount, Answers: $ancount, Authority: $nscount, Additional: $arcount\n";

        if ($ancount > 0) {
            print "Audit credential registered successfully!\n";
        } else {
            print "No answers in DNS response\n";
        }
    } else {
        print "No response from audit resolver\n";
    }

    $socket->close();
} else {
    print "Failed to connect to audit resolver on port 47302: $!\n";
    print "This may mean the audit service is not running or the port is blocked.\n";
}
